import { NextRequest,NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabaseAdmin";
import { hash } from "@/lib/runnerAuth";
import { replayRun,RUNNER } from "@/lib/runnerEngine";
export const dynamic="force-dynamic";
export async function POST(req:NextRequest){try{const b=await req.json();if(!b.runId||!b.runToken||!Array.isArray(b.jumpTicks)||b.jumpTicks.length>800||!b.jumpTicks.every((x:unknown)=>Number.isInteger(x)&&Number(x)>=0&&Number(x)<=RUNNER.maxTicks)||!Number.isInteger(b.claimedScore))return NextResponse.json({error:"Invalid submission"},{status:400});const db=getSupabaseAdmin();const {data:r}=await db.from("runner_runs").select("*").eq("id",b.runId).maybeSingle();if(!r||r.status!=="active"||r.run_token_hash!==hash(b.runToken))return NextResponse.json({error:"Invalid or used run"},{status:401});const replay=replayRun(r.seed,b.jumpTicks);const expected=replay.tick*RUNNER.fixedStepMs,actual=Date.now()-new Date(r.started_at).getTime();const plausible=actual>=Math.max(0,expected-2500)&&actual<=expected+20000;const matches=Math.abs(replay.score-b.claimedScore)<=2;if(!replay.collided||!plausible||!matches){await db.from("runner_runs").update({status:"rejected",submitted_at:new Date().toISOString(),rejection_reason:!replay.collided?"No validated collision":!matches?"Score mismatch":"Implausible duration"}).eq("id",r.id);return NextResponse.json({error:"Score failed server validation"},{status:422});}await db.from("runner_runs").update({status:"accepted",validated_score:replay.score,jump_count:b.jumpTicks.length,submitted_at:new Date().toISOString()}).eq("id",r.id).eq("status","active");const {data:existing}=await db.from("runner_scores").select("best_score").eq("wallet",r.wallet).eq("week_start",r.week_start).maybeSingle();if(!existing||replay.score>existing.best_score)await db.from("runner_scores").upsert({wallet:r.wallet,nickname:r.nickname,week_start:r.week_start,best_score:replay.score,best_run_id:r.id,updated_at:new Date().toISOString()},{onConflict:"wallet,week_start"});return NextResponse.json({accepted:true,score:replay.score});}catch(e){console.error(e);return NextResponse.json({error:"Unable to validate score"},{status:500});}}
